class Parser:
    def __init__(self, expression):
        self.expression = expression
        self.index = 0

    def parse(self):
        self.skip_whitespace()
        value = self.parse_expression()
        if self.index < len(self.expression):
            raise SyntaxError("Unexpected characters at the end of the expression.")
        return value

    def parse_expression(self):
        value = self.parse_term()
        while self.index < len(self.expression):
            self.skip_whitespace()
            if self.peek() in ('+', '-'):
                operator = self.next()
                self.skip_whitespace()
                if operator == '+':
                    value += self.parse_term()
                elif operator == '-':
                    value -= self.parse_term()
            else:
                break
        return value

    def parse_term(self):
        value = self.parse_factor()
        while self.index < len(self.expression):
            self.skip_whitespace()
            if self.peek() in ('*', '/'):
                operator = self.next()
                self.skip_whitespace()
                if operator == '*':
                    value *= self.parse_factor()
                elif operator == '/':
                    value /= self.parse_factor()
            else:
                break
        return value

    def parse_factor(self):
        self.skip_whitespace()
        if self.peek() == '(':
            self.next()
            value = self.parse_expression()
            self.skip_whitespace()
            if self.peek() != ')':
                raise SyntaxError("Missing closing parenthesis.")
            self.next()
            return value
        return self.parse_number()

    def parse_number(self):
        start_index = self.index
        while (self.index < len(self.expression) and
               (self.peek().isdigit() or self.peek() in '.-')):
            self.index += 1
        if start_index == self.index:
            raise SyntaxError("Expected a number.")
        return float(self.expression[start_index:self.index])

    def peek(self):
        return self.expression[self.index] if self.index < len(self.expression) else ''

    def next(self):
        char = self.peek()
        self.index += 1
        return char

    def skip_whitespace(self):
        while self.index < len(self.expression) and self.peek().isspace():
            self.index += 1


