class Token:
    NUMBER, PLUS, MINUS, TIMES, DIVIDE, LPAREN, RPAREN, EOF = (
        'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'LPAREN', 'RPAREN', 'EOF'
    )

    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value


class Lexer:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.position += 1
        self.current_char = self.expression[self.position] if self.position < len(self.expression) else None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def get_number(self):
        number_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number_str += self.current_char
            self.advance()
        return Token(Token.NUMBER, float(number_str))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.get_number()
            if self.current_char == '+':
                self.advance()
                return Token(Token.PLUS)
            if self.current_char == '-':
                self.advance()
                return Token(Token.MINUS)
            if self.current_char == '*':
                self.advance()
                return Token(Token.TIMES)
            if self.current_char == '/':
                self.advance()
                return Token(Token.DIVIDE)
            if self.current_char == '(':
                self.advance()
                return Token(Token.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(Token.RPAREN)

            self.error()
        return Token(Token.EOF)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type == Token.NUMBER:
            self.eat(Token.NUMBER)
            return token.value
        elif token.type == Token.LPAREN:
            self.eat(Token.LPAREN)
            result = self.expr()
            self.eat(Token.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.type in (Token.TIMES, Token.DIVIDE):
            token = self.current_token
            if token.type == Token.TIMES:
                self.eat(Token.TIMES)
                result *= self.factor()
            elif token.type == Token.DIVIDE:
                self.eat(Token.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type in (Token.PLUS, Token.MINUS):
            token = self.current_token
            if token.type == Token.PLUS:
                self.eat(Token.PLUS)
                result += self.term()
            elif token.type == Token.MINUS:
                self.eat(Token.MINUS)
                result -= self.term()
        return result


